  if(r->n==r->cap){r->cap=r->cap*2+8;r->c=realloc(r->c,r->cap*sizeof(int));} r->c[r->n++]=j;}
/* heap of (d, j) */
static double *hd; static int *hj; static int hn;
static void hpush(double d,int j){int i=hn++; while(i>0){int p=(i-1)/2; if(hd[p]<=d)break; hd[i]=hd[p];hj[i]=hj[p];i=p;} hd[i]=d;hj[i]=j;}
static void hpop(){ double d=hd[--hn]; int j=hj[hn]; int i=0; for(;;){int l=2*i+1; if(l>=hn)break; if(l+1<hn&&hd[l+1]<hd[l])l++; if(hd[l]>=d)break; hd[i]=hd[l];hj[i]=hj[l];i=l;} hd[i]=d;hj[i]=j;}

static int jv(int n,const double*M,Row*R,int*x,int*y,double*v,int maxe){
  /* x: row->col, y: col->row */
  for(int j=0;j<n;j++){v[j]=INFINITY;y[j]=-1;}
  int *amin=malloc(n*sizeof(int));
  for(int i=0;i<n;i++){x[i]=-1; const double*Mi=M+(size_t)i*n; for(int t=0;t<R[i].n;t++){int j=R[i].c[t]; if(Mi[j]<v[j]){v[j]=Mi[j];amin[j]=i;}}}
  for(int j=0;j<n;j++){ if(v[j]==INFINITY){free(amin);return -1;} int i=amin[j]; if(x[i]<0){x[i]=j;y[j]=i;} }
  free(amin);
  double *d=malloc(n*sizeof(double)); int *pred=malloc(n*sizeof(int)); char *sc=calloc(n,1);
  int *touched=malloc(n*sizeof(int)); int *scl=malloc(n*sizeof(int));
  hd=malloc((maxe+n+8)*sizeof(double)); hj=malloc((maxe+n+8)*sizeof(int));
  for(int j=0;j<n;j++) d[j]=INFINITY;
  int ok=0;
  for(int f=0;f<n;f++){ if(x[f]>=0) continue;
    int nt=0, ns=0; hn=0;
    const double*Mf=M+(size_t)f*n;
    for(int t=0;t<R[f].n;t++){int j=R[f].c[t]; double dd=Mf[j]-v[j]; if(dd<d[j]){ if(d[j]==INFINITY) touched[nt++]=j; d[j]=dd; pred[j]=f; hpush(dd,j);} }
    int end=-1; double mu=0;
    while(hn>0){ double dj=hd[0]; int j=hj[0]; hpop(); if(sc[j]||dj>d[j]) continue;
      if(y[j]<0){end=j;mu=dj;break;}
      sc[j]=1; scl[ns++]=j; int i=y[j]; const double*Mi=M+(size_t)i*n; double base=dj-(Mi[j]-v[j]);
      for(int t=0;t<R[i].n;t++){int k=R[i].c[t]; if(sc[k])continue; double nd=base+Mi[k]-v[k]; if(nd<d[k]){ if(d[k]==INFINITY) touched[nt++]=k; d[k]=nd; pred[k]=i; hpush(nd,k);} }
    }
    if(end<0){ok=-1;}
    else {
      for(int t=0;t<ns;t++){int k=scl[t]; v[k]+=d[k]-mu;}
      int j=end; for(;;){int i=pred[j]; y[j]=i; int pj=x[i]; x[i]=j; if(i==f)break; j=pj;}
    }
    for(int t=0;t<nt;t++) d[touched[t]]=INFINITY;
    for(int t=0;t<ns;t++) sc[scl[t]]=0;
    if(ok) break;
  }
  free(d);free(pred);free(sc);free(touched);free(scl);free(hd);free(hj);
  return ok;
}

int solve(int n,const double*M,int k,int*x){
  Row*R=calloc(n,sizeof(Row));
  if(k>n)k=n;
  double *bd=malloc((k+1)*sizeof(double)); int *bj=malloc((k+1)*sizeof(int));
  for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; int c=0;
    for(int j=0;j<n;j++){double m=Mi[j]; if(c==k && m>=bd[k-1]) continue; int p=(c<k)?c++:k-1; while(p>0&&bd[p-1]>m){bd[p]=bd[p-1];bj[p]=bj[p-1];p--;} bd[p]=m;bj[p]=j;}
    for(int t=0;t<c;t++) add(&R[i],bj[t]); }
  /* column k-nearest */
  {double *cd=malloc((size_t)n*k*sizeof(double)); int *ci=malloc((size_t)n*k*sizeof(int)); int *cc=calloc(n,sizeof(int));
   for(int i=0;i<n;i++){const double*Mi=M+(size_t)i*n; for(int j=0;j<n;j++){double m=Mi[j]; double*D=cd+(size_t)j*k; int*I=ci+(size_t)j*k; int c=cc[j];
      if(c==k && m>=D[k-1]) continue; int p=(c<k)?cc[j]++:k-1; while(p>0&&D[p-1]>m){D[p]=D[p-1];I[p]=I[p-1];p--;} D[p]=m;I[p]=i;}}
   for(int j=0;j<n;j++) for(int t=0;t<cc[j];t++) add(&R[ci[(size_t)j*k+t]],j);
   free(cd);free(ci);free(cc);}
  free(bd);free(bj);
  int *y=malloc(n*sizeof(int)); double *v=malloc(n*sizeof(double));
  int ret=-1;
  for(int it=0; it<20; it++){
    int E=0; for(int i=0;i<n;i++) E+=R[i].n;
    int r=jv(n,M,R,x,y,v,E);
    if(r<0){ /* add more edges: next nearest by full rows */ for(int i=0;i<n;i++) for(int j=0;j<n;j++) add(&R[i],j); continue; }
    int viol=0;
    for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; double u=Mi[x[i]]-v[x[i]];
      for(int j=0;j<n;j++){ if(Mi[j]-v[j]-u < -1e-12){ add(&R[i],j); viol++; } } }
    if(!viol){ret=0;break;}
  }
  for(int i=0;i<n;i++) free(R[i].c); free(R); free(y); free(v);
  return ret;
}
