  for(int i=0;i<n;i++){const double*Mi=M+(size_t)i*n; for(int j=0;j<n;j++){ if(Mi[j]<v[j]){v[j]=Mi[j];cam[j]=i;} }}
  /* threshold on reduced cost M-v: sample */
  int S=4096; double *smp=malloc(S*sizeof(double)); unsigned s=12345u;
  for(int t=0;t<S;t++){ s=s*1664525u+1013904223u; unsigned i=(s>>8)%n; s=s*1664525u+1013904223u; unsigned j=(s>>8)%n; smp[t]=M[(size_t)i*n+j]-v[j]; }
  qsort(smp,S,sizeof(double),cmpd);
