    double th = T + (rm>0?rm:0);
    for(int j=0;j<n;j++){ if(Mi[j]-v[j]<=th){ add(&R[i],j,Mi[j]); f[j]=1; } }
    if(!f[ra]){add(&R[i],ra,Mi[ra]); f[ra]=1;}
    if(!f[i]){add(&R[i],i,Mi[i]); f[i]=1;} /* ensures perfect matching exists */
  }
