        int _i=hn++; double _d=(dd); int _j=(jj); while(_i>0){int _p=(_i-1)>>1; if(hd[_p]<=_d)break; hd[_i]=hd[_p];hj[_i]=hj[_p];_i=_p;} hd[_i]=_d;hj[_i]=_j; }while(0)
