      for(int t=0;t<ns;t++) sc[scl[t]]=0;
    }
    double t2=now();
    /* verify */
    int viol=0;
    for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; double u=Mi[x[i]]-v[x[i]]-1e-12;
