#define NTH 6
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+1e-9*t.tv_nsec;}
typedef struct {int *c; double *w; int n, cap;} Row;
static void add(Row*r,int j,double w){
  if(r->n==r->cap){r->cap=r->cap*2+16;r->c=realloc(r->c,r->cap*sizeof(int));r->w=realloc(r->w,r->cap*sizeof(double));}
  r->c[r->n]=j; r->w[r->n]=w; r->n++;}
static int cmpd(const void*a,const void*b){double x=*(double*)a,y=*(double*)b;return x<y?-1:x>y;}
static const double*gv; static int cmpv(const void*a,const void*b){double x=gv[*(int*)a],y=gv[*(int*)b];return x>y?-1:x<y;}

typedef struct {int n; const double*M; Row*R; double T; int i0,i1;} BArg;
static void* bwork(void*vp){ BArg*a=vp; int n=a->n; const double*M=a->M; double T=a->T;
  int *tmp=malloc((n+4)*sizeof(int));
  for(int i=a->i0;i<a->i1;i++){const double*Mi=M+(size_t)i*n;
    int cnt=0; for(int j=0;j<n;j++){ tmp[cnt]=j; cnt += (Mi[j]<=T); }
    if(Mi[i]>T) tmp[cnt++]=i;
    if(cnt<2){int j=(i+1)%n; if(j!=tmp[0]) tmp[cnt++]=j;}
    Row*Ri=&a->R[i]; Ri->cap=cnt+32; Ri->n=cnt; Ri->c=malloc(Ri->cap*sizeof(int)); Ri->w=malloc(Ri->cap*sizeof(double));
    for(int t=0;t<cnt;t++){ Ri->c[t]=tmp[t]; Ri->w[t]=Mi[tmp[t]]; }
  }
  free(tmp); return NULL; }

/* verify: for each row i, add edges with M_ij - v_j < u_i - tol, where u_i = M[i,x_i]-v[x_i]; edges in graph satisfy M<=T or were added (flag via M>T test + not present).
   Since graph = {M<=T} U extra, we check presence for M>T edges by scanning row list (rare). */
typedef struct {int n; const double*M; Row*R; double T; int i0,i1; int*x; const double*v; const int*ord; double tol; int viol; int bad; char*badr;} VArg;
static void* vwork(void*vp){ VArg*a=vp; int n=a->n; const double*M=a->M; double T=a->T; const double*v=a->v; const int*ord=a->ord; int*x=a->x;
  int viol=0, nb=0;
  for(int i=a->i0;i<a->i1;i++){ const double*Mi=M+(size_t)i*n; double u=Mi[x[i]]-v[x[i]]-a->tol;
      double lim=T-u; int bad=0;
      for(int k=0;k<n;k++){ int j=ord[k]; if(v[j]<=lim) break;
        if(Mi[j]-v[j]<u){ bad=1; if(Mi[j]>T){ Row*Ri=&a->R[i]; int has=0; for(int q=Ri->n-1;q>=0;q--) if(Ri->c[q]==j){has=1;break;}
            if(!has){ add(Ri,j,Mi[j]); viol++; } } } }
      a->badr[i]=bad; nb+=bad;
  }
  a->viol=viol; a->bad=nb; return NULL; }

static void verify(int n,const double*M,Row*R,double T,int*x,double*v,int*ord,double tol,int*viol,int*nbad,char*badr){
  for(int j=0;j<n;j++) ord[j]=j;
  gv=v; qsort(ord,n,sizeof(int),cmpv);
  VArg va[NTH]; pthread_t th[NTH];
  for(int k=0;k<NTH;k++){ va[k].n=n; va[k].M=M; va[k].R=R; va[k].T=T; va[k].i0=n*k/NTH; va[k].i1=n*(k+1)/NTH; va[k].x=x; va[k].v=v; va[k].ord=ord; va[k].tol=tol; va[k].badr=badr; }
  for(int k=1;k<NTH;k++) pthread_create(&th[k],NULL,vwork,&va[k]);
  vwork(&va[0]);
  for(int k=1;k<NTH;k++) pthread_join(th[k],NULL);
  *viol=0; *nbad=0; for(int k=0;k<NTH;k++){ *viol+=va[k].viol; *nbad+=va[k].bad; }
}

/* auction (min-cost form, prices p, row picks min w+p). warm: keep assignment of rows satisfying eps-CS */
static long auction(int n,Row*R,int*x,int*y,double*p,int*freel,double eps,int warm,long cap){
  int nf=0;
  if(!warm){ for(int i=0;i<n;i++)x[i]=-1; for(int j=0;j<n;j++)y[j]=-1; nf=n; for(int i=0;i<n;i++)freel[i]=n-1-i; }
  else { for(int i=n-1;i>=0;i--){ if(x[i]<0){freel[nf++]=i; continue;} Row*Ri=&R[i]; double m=INFINITY,cur=INFINITY; int xi=x[i];
        for(int t=0;t<Ri->n;t++){ int j=Ri->c[t]; double h=Ri->w[t]+p[j]; if(h<m)m=h; if(j==xi)cur=h; }
        if(cur>m+eps){ y[xi]=-1; x[i]=-1; freel[nf++]=i; } } }
  long pb=0;
  while(nf>0){ if(++pb>cap) return -1; int i=freel[--nf]; Row*Ri=&R[i];
    double w1=INFINITY,w2=INFINITY; int j1=-1;
    for(int t=0;t<Ri->n;t++){ double h=Ri->w[t]+p[Ri->c[t]]; if(h<w2){ if(h<w1){w2=w1;w1=h;j1=Ri->c[t];} else w2=h; } }
    if(w2==INFINITY) w2=w1+1.0;
    p[j1]+=w2-w1+eps;
    int o=y[j1]; if(o>=0){x[o]=-1; freel[nf++]=o;}
    y[j1]=i; x[i]=j1;
  }
