}

int solve(int n,const double*M,int*x,double epsf,double factor,double eps0,double tol){
  int dbg=getenv("EMDDBG")!=NULL;
  double t0=now();
  int np=(n+7)&~7;
  float *Mf=aligned_alloc(32,(size_t)n*np*sizeof(float));
  float *p=aligned_alloc(32,np*sizeof(float));
  for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; float*F=Mf+(size_t)i*np; for(int j=0;j<n;j++) F[j]=(float)Mi[j]; for(int j=n;j<np;j++) F[j]=1e30f; }
  for(int j=0;j<np;j++) p[j]=0;
  int *y=malloc(n*sizeof(int)), *freel=malloc(n*sizeof(int));
  double t1=now();
  long cap=(long)n*400; int ret=-1;
  double eps=eps0; int warm=0; long tb=0;
  for(;;){ long b=auction(n,np,Mf,x,y,p,freel,(float)eps,warm,cap); warm=1;
    if(dbg) fprintf(stderr,"phase eps %g bids %ld t %.3f\n",eps,b,(now()-t1)*1e3);
    if(b<0){ ret=-3; goto done; } tb+=b;
    if(eps<=epsf) break; eps/=factor; if(eps<epsf) eps=epsf; }
  double t2=now();
  /* exact phase in double, dense */
  { double *v=malloc(n*sizeof(double)), *d=malloc(n*sizeof(double)); int *pred=malloc(n*sizeof(int)); char*sc=malloc(n);
    int *todo=malloc(n*sizeof(int)), *scl=malloc(n*sizeof(int));
    for(int j=0;j<n;j++) v[j]=-(double)p[j];
    int nfree=0;
    for(int it=0; it<20; it++){
      /* verify CS: u_i = min_j M_ij - v_j ; bad if assigned reduced > u+tol */
      nfree=0;
      for(int i=0;i<n;i++){ const double*Mi=M+(size_t)i*n; double mn=INFINITY; for(int j=0;j<n;j++){ double r=Mi[j]-v[j]; mn=r<mn?r:mn; }
        if(x[i]<0 || Mi[x[i]]-v[x[i]]>mn+tol){ if(x[i]>=0){ y[x[i]]=-1; x[i]=-1; } todo[nfree++]=i; } }
      if(dbg) fprintf(stderr,"exact it %d free %d t %.3f\n",it,nfree,(now()-t1)*1e3);
      if(nfree==0){ ret=it; break; }
      /* dense Dijkstra augment for each free row */
      for(int q=0;q<nfree;q++){ int f=todo[q]; const double*Mf0=M+(size_t)f*n;
        for(int j=0;j<n;j++){ d[j]=Mf0[j]-v[j]; pred[j]=f; sc[j]=0; }
        int ns=0, end=-1; double mu=0;
        for(;;){ int jm=-1; double dm=INFINITY; for(int j=0;j<n;j++) if(!sc[j] && d[j]<dm){dm=d[j];jm=j;}
          if(jm<0) break;
          if(y[jm]<0){ end=jm; mu=dm; break; }
          sc[jm]=1; scl[ns++]=jm; int i=y[jm]; const double*Mi=M+(size_t)i*n; double base=dm-(Mi[jm]-v[jm]);
          for(int j=0;j<n;j++){ if(sc[j]) continue; double nd=base+Mi[j]-v[j]; if(nd<d[j]){d[j]=nd;pred[j]=i;} } }
        if(end<0){ ret=-2; break; }
        for(int t=0;t<ns;t++){int k=scl[t]; v[k]+=d[k]-mu;}
        { int j=end; for(;;){int i=pred[j]; y[j]=i; int pj=x[i]; x[i]=j; if(i==f)break; j=pj;} }
      }
      if(ret==-2) break;
      tol=1e-12;
    }
    free(v);free(d);free(pred);free(sc);free(todo);free(scl);
  }
  if(dbg) fprintf(stderr,"SUM conv %.3f auc %.3f (bids %ld) exact %.3f total %.3f\n",(t1-t0)*1e3,(t2-t1)*1e3,tb,(now()-t2)*1e3,(now()-t0)*1e3);
done:
  free(Mf);free(p);free(y);free(freel);
  return ret;
}
